# ---------------- Lecture 9 ----------------
add("L9.D21","L9","§2.1 Definition 2.1","Definition 2.1.",r"$S\subseteq T$ is **upper bounded** if $\exists u\in T$ with $s\le u$ for all $s\in S$ ($u$ is an upper bound); **lower bounded** if $\exists l\in T$ with $l\le s$ for all $s\in S$; **bounded** if both.")
add("L9.R1","L9","§2.1 Remark 1","Remark 1. Let S",r"Anything above an upper bound is an upper bound; anything below a lower bound is a lower bound.")
add("L9.D22","L9","§2.1 Definition 2.2","Definition 2.2.",r"$u^*$ is the **supremum** (least upper bound) of $S$ if $u^*$ is an upper bound and $u^*\le u$ for every upper bound $u$. The **infimum** $l^*$ is a lower bound with $l\le l^*$ for every lower bound $l$.")
add("L9.P21","L9","§2.1 Proposition 2.1","Proposition 2.1.",r"If $S$ has a supremum, it is unique.")
add("L9.E21","L9","§2.1 Example 2.1","Example 2.1.",r"$H_+=\{\tfrac1n : n\in\mathbb N\}\subseteq\mathbb Q$. Prove $\sup H_+=1$ in two steps: 1 is an upper bound, and every upper bound $u$ has $1\le u$.")
add("L9.R2","L9","§2.1 Remark 2","Remark 2. Here",r"Here the supremum $1$ is an element of $H_+$.")
add("L9.E22","L9","§2.1 Example 2.2","Example 2.2.",r"$H_-=\{-\tfrac1n : n\in\mathbb N\}$. Prove $\sup H_-=0$ in two steps.")
add("L9.R3","L9","§2.1 Remark 3","Remark 3. Here",r"Here the supremum $0$ is in $\mathbb Q$ but **not** in $H_-$.")
add("L9.D23","L9","§2.1 Definition 2.3","Definition 2.3.",r"If $\sup S\in S$ it is the **maximum** $\max S$; if $\inf S\in S$ it is the **minimum** $\min S$.")
add("L9.D24","L9","§2.1 Definition 2.4","Definition 2.4.",r"A totally ordered set $T$ is **complete** if every nonempty upper bounded subset has a supremum in $T$.")
add("L9.D25","L9","§2.1 Definition 2.5","Definition 2.5.",r"An ordered field is a **complete ordered field** if every nonempty upper bounded subset has a supremum in it.")
add("L9.R4","L9","§2.1 Remark 4","Remark 4.",r"Completeness is a property of the total order; it doesn't need the field structure.")
add("L9.R5","L9","§2.1 Remark 5","Remark 5.",r"In a complete totally ordered set, every nonempty lower bounded subset has an infimum. Why?")
add("L9.T21","L9","§2.2 Theorem 2.1","Theorem 2.1.",r"There is no $q\in\mathbb Q$ with $q^2=2$.")
add("L9.R6","L9","§2.2 Remark 6","Remark 6.",r"The diagonal of a unit square has length $x$ with $x^2=2$, so some lengths are not rational.")
add("L9.T22","L9","§2.2 Theorem 2.2","Theorem 2.2.",r"$\mathbb Q$ is not complete: $S=\{x\in\mathbb Q: x>0,\ x^2<2\}$ is nonempty and upper bounded but has no supremum in $\mathbb Q$.")
add("L9.T23","L9","§2.2 Theorem 2.3","Theorem 2.3.",r"There is a unique (up to isomorphism) complete ordered field $(\mathbb R,+,\cdot,<)$, and it contains a copy of $\mathbb Q$.")
add("L9.CA","L9","§2.2 Completeness axiom","Completeness axiom for the real numbers",r"**Completeness axiom.** Every nonempty subset of $\mathbb R$ that is upper bounded has a supremum.")
add("L9.R7","L9","§2.2 Remark 7","Remark 7.",r"'Unique up to isomorphism': any complete ordered field $F_1$ has a bijection $g:F_1\to\mathbb R$ preserving $+$, $\cdot$ and $<$.")
add("L9.T24","L9","§2.2 Theorem 2.4","Theorem 2.4.",r"There is a unique positive $x\in\mathbb R$ with $x^2=2$.")
add("L9.R8","L9","§2.2 Remark 8","Remark 8.",r"So $\sqrt2\in\mathbb R\setminus\mathbb Q$: irrational numbers exist.")

# ---------------- Lecture 10 ----------------
add("L10.P11","L10","§1 Proposition 1.1 (template)","Proposition 1.1.",r"Template for $u^*=\sup S$: (i) show $s\le u^*$ for all $s\in S$; (ii) show $u^*\le u$ for every upper bound $u$, **or** show any $u<u^*$ is not an upper bound.")
add("L10.E11","L10","§1 Example 1.1","Example 1.1.",r"$S=(-\infty,1)$ has $\sup S=1$ (midpoint argument).")
add("L10.P21","L10","§2 Proposition 2.1","Proposition 2.1.",r"For $S$ nonempty, upper bounded: $u^*=\sup S$ iff (a) $u^*$ is an upper bound and (b) $\forall\varepsilon>0\ \exists x\in S$ with $x>u^*-\varepsilon$.")
add("L10.GM","L10","§2 Geometric meaning","Geometric meaning.",r"Every window $(u^*-\varepsilon,u^*]$ just left of the sup contains a point of $S$: $S\cap(u^*-\varepsilon,u^*]\ne\varnothing$.")
add("L10.R1","L10","§2 Remark 1","Remark 1. Proposition 2.1 implies",r"A supremum can be approximated arbitrarily well by elements of the set, e.g. $\sup(0,1)=1$.")
add("L10.R2","L10","§2 Remark 2","Remark 2. A similar",r"State the analogous $\varepsilon$-characterization of the infimum.")
add("L10.R3","L10","§2 Remark 3 (nested quantifiers)","Remark 3 (Nested quantifiers",r"$\forall x\,\exists y\,P(x,y)$ (y may depend on x) is different from $\exists y\,\forall x\,P(x,y)$ (one y for all x).")
add("L10.T31","L10","§3 Theorem 3.1","Theorem 3.1.",r"$\mathbb N$ is not upper bounded in $\mathbb R$.")
add("L10.T32","L10","§3 Theorem 3.2 (Archimedean)","Theorem 3.2 (Archimedean",r"For $\varepsilon>0$ and $a\in\mathbb R$ there is $n\in\mathbb N$ with $n\varepsilon>a$.")
add("L10.T33","L10","§3 Theorem 3.3","Theorem 3.3.",r"For every $\varepsilon>0$ there is $n\in\mathbb N$ with $0<\tfrac1n<\varepsilon$.")
add("L10.P41","L10","§4 Proposition 4.1","Proposition 4.1.",r"$\mathbb R_{>0}$ has no least element.")
add("L10.X41","L10","§4 Exercise 4.1","Exercise 4.1.",r"If $x<y+\varepsilon$ for every $\varepsilon>0$, then $x\le y$.")
add("L10.T41","L10","§4 Theorem 4.1 (integer part)","Theorem 4.1 (Existence of the integer part)",r"For every $x\in\mathbb R$ there is a unique $m\in\mathbb Z$ with $m\le x<m+1$.")
add("L10.D41","L10","§4 Definition 4.1","Definition 4.1.",r"The integer part $[x]$: $[x]\le x<[x]+1$.")
add("L10.E41","L10","§4 Example 4.1","Example 4.1.",r"$[2.7]=2$, $[-2.7]=-3$.")
add("L10.T42","L10","§4 Theorem 4.2 (density of Q)","Theorem 4.2 (Density",r"If $x<y$ there is $q\in\mathbb Q$ with $x<q<y$ (take $q=([nx]+1)/n$ with $n(y-x)>1$).")
add("L10.Q","L10","§4 closing Question","Are the irrationals also dense",r"Are the irrationals also dense on the real line?")

# ---------------- Lecture 11 ----------------
add("L11.S1","L11","§1 Motivation: $x^2=-1$","Motivation for complex numbers",r"No real $x$ has $x^2=-1$; with $i^2=-1$ every real quadratic can be solved.")
add("L11.S2","L11","§2 Interlude: algebraically closed","Interlude: polynomial equations",r"$\mathbb N\subsetneq\mathbb Z\subsetneq\mathbb Q\subsetneq\mathbb R\subsetneq\mathbb C$. Fundamental Theorem of Algebra: every nonconstant complex polynomial has a root in $\mathbb C$, so $\mathbb C$ is **algebraically closed**.")
add("L11.D41","L11","§4 Definition 4.1","Definition 4.1.",r"$\mathbb C=\mathbb R^2$ with $(x,y)+(u,v)=(x+u,y+v)$ and $(x,y)(u,v)=(xu-yv,\,xv+yu)$.")
add("L11.T41","L11","§4 Theorem 4.1","Theorem 4.1.",r"$\mathbb C$ is a field with $0=(0,0)$, $1=(1,0)$; $(x,y)^{-1}=\left(\frac{x}{x^2+y^2},\frac{-y}{x^2+y^2}\right)$.")
add("L11.R1","L11","§4 Remark 1","Remark 1. If we defined",r"Componentwise multiplication fails: $(1,0)(0,1)=(0,0)$ with neither factor zero.")
add("L11.D42","L11","§4 Definition 4.2","Definition 4.2.",r"$i=(0,1)$.")
add("L11.P41","L11","§4 Proposition 4.1","Proposition 4.1.",r"$i^2=-1$.")
add("L11.R2","L11","§4 Remark 2","Remark 2. This construction",r"Any field containing $\mathbb R$ and $j$ with $j^2=-1$ contains every $x+yj$.")
add("L11.D43","L11","§4 Definition 4.3","Definition 4.3.",r"$\operatorname{Re}(x,y)=x$, $\operatorname{Im}(x,y)=y$; write $(x,y)=x+iy$.")
add("L11.P42","L11","§4 Proposition 4.2","Proposition 4.2.",r"No order makes $\mathbb C$ an ordered field ($i^2>0$ would give $-1>0$).")
add("L11.E41","L11","§4 Example 4.1","Example 4.1.",r"$(2+3i)+(4+5i)$, $(2+3i)(4+5i)=-7+22i$, $\frac1{2+3i}=\frac2{13}-\frac3{13}i$.")
add("L11.D51","L11","§5 Definition 5.1 (Fig. 3)","Definition 5.1.",r"Conjugate $\bar z=x-iy$: reflection across the real axis.")
add("L11.D52","L11","§5 Definition 5.2 (Fig. 4)","Definition 5.2.",r"Modulus $|z|=\sqrt{x^2+y^2}$: distance from $0$.")
add("L11.R3","L11","§5 Remark 3","Remark 3. If r",r"For real $r$, the modulus equals the absolute value $\sqrt{r^2}$.")
add("L11.R4","L11","§5 Remark 4","Remark 4. For z",r"$z\bar z=|z|^2$, so $\frac1z=\frac{\bar z}{|z|^2}$: divide by multiplying by the conjugate.")
add("L11.EX","L11","§5 Examples (i)–(ii)","Write the following complex numbers",r"$\frac{4-i}{3+2i}=\frac{10}{13}-\frac{11}{13}i$; $\frac1{2+3i}+\frac{1-i}{2-3i}=\frac7{13}-\frac2{13}i$.")
add("L11.PR","L11","§5 Properties (i)–(xii)","Properties of the conjugate and the modulus",r"$\bar{\bar z}=z$, $\overline{z+w}=\bar z+\bar w$, $z+\bar z=2\operatorname{Re}z$, $\overline{zw}=\bar z\bar w$, $\overline{z/w}=\bar z/\bar w$, $z=\bar z\iff z\in\mathbb R$, $|\bar z|=|z|$, $z\bar z=|z|^2$, $|zw|=|z||w|$, $|\operatorname{Re}z|,|\operatorname{Im}z|\le|z|$, (xii) $|z+w|\le|z|+|w|$.")

# ---------------- Lecture 12 ----------------
add("L12.PR","L12","§1 Proofs of (i)–(xi)","We will prove the following properties",r"Proofs of the conjugate and modulus properties (i)–(xi), e.g. $|zw|^2=zw\,\bar z\bar w=|z|^2|w|^2$.")
add("L12.PX","L12","§1 Proof of (xii) triangle inequality","Triangle inequality: |z + w|",r"$|z+w|^2=|z|^2+|w|^2+2\operatorname{Re}(z\bar w)\le(|z|+|w|)^2$.")
add("L12.P11","L12","§1 Proposition 1.1","is a unit vector",r"For $z\ne0$, $\left|\frac z{|z|}\right|=1$.")
add("L12.D21","L12","§2 Definition 2.1","Definition 2.1.",r"An argument $\theta$ of $z\ne0$; polar form $z=|z|(\cos\theta+i\sin\theta)$.")
add("L12.R1","L12","§2 Remark 1","Remark 1. An argument",r"Arguments are defined up to $2\pi k$; these notes use $[0,2\pi)$.")
add("L12.R2","L12","§2 Remark 2","Remark 2. We have",r"$\tan\theta=\operatorname{Im}z/\operatorname{Re}z$ doesn't determine $\theta$; $\tan^{-1}$ only works when $\operatorname{Re}z>0$. Check the quadrant.")
add("L12.E21","L12","§2 Example 2.1","Example 2.1.",r"$7+7i=7\sqrt2\left(\cos\frac\pi4+i\sin\frac\pi4\right)$.")
add("L12.X21","L12","§2 Exercise 2.1","Exercise 2.1.",r"Polar form of $z_1=\sqrt3+i$, $z_2=-1+i$, $z_3=-\sqrt3-i$; sketch them.")
add("L12.E22","L12","§2 Example 2.2","Example 2.2.",r"$3+5i=\sqrt{34}(\cos\theta+i\sin\theta)$, $\theta=\tan^{-1}(5/3)$.")
add("L12.ADD","L12","§3 Parallelogram rule","parallelogram rule",r"Addition in $\mathbb C$ is vector addition (parallelogram rule).")
add("L12.TRI","L12","§3 Triangle-inequality picture","This explains why it is called the triangle inequality",r"$0$, $z$, $z+w$ form a triangle with sides $|z|,|w|,|z+w|$.")
add("L12.QEQ","L12","§3 Question (equality case)","When does equality hold",r"When does $|z+w|=|z|+|w|$? Interpret geometrically.")
add("L12.MUL","L12","§3 Multiplication in polar form","angles add and lengths",r"$zw=|z||w|\big(\cos(\theta+\psi)+i\sin(\theta+\psi)\big)$: lengths multiply, angles add.")
add("L12.DM","L12","§3 de Moivre's formula","Moivre",r"$\big(r(\cos\theta+i\sin\theta)\big)^n=r^n(\cos n\theta+i\sin n\theta)$.")
add("L12.E31","L12","§3 Example 3.1","Example 3.1.",r"$z=\frac{\sqrt3}2+\frac i2$: compute $z^2,z^3,\dots,z^{13}=z$.")
add("L12.QI","L12","§3 Question (multiply by i)","What is the effect of multiplying",r"What is the effect of multiplying $z$ by $i$?")
add("L12.X31","L12","§3 Exercise 3.1","Exercise 3.1.",r"Find $i^n$ by the remainder of $n$ mod 4; plot $i^0,\dots,i^7$.")
add("L12.D41","L12","§4 Definition 4.1","Definition 4.1.",r"$z$ is an $n$th root of unity if $z^n=1$.")
add("L12.RU","L12","§4 Derivation of the roots","Two obser",r"$z_k=\cos\frac{2\pi k}n+i\sin\frac{2\pi k}n$, $k=0,\dots,n-1$: exactly $n$ roots.")
add("L12.GI","L12","§4 Geometric interpretation","Geometric interpretation",r"The roots are equally spaced on the unit circle (angle $2\pi/n$), vertices of a regular $n$-gon.")
add("L12.E41","L12","§4 Example 4.1","The fourth roots of unity",r"Fourth roots of unity: $1,i,-1,-i$ (a square).")
add("L12.X41","L12","§4 Exercise 4.1","Exercise 4.1.",r"Find and plot the third roots of unity; why an equilateral triangle?")

# ---------------- Lecture 13 ----------------
add("L13.D11","L13","§1 Definition 1.1","Definition 1.1.",r"$|x|=x$ if $x\ge0$, $-x$ if $x<0$, in any ordered field.")
add("L13.R11","L13","§1 Remarks 1.1–1.2","Remark 1.1.",r"$0$ and $-x$ are the field's additive identity and inverse; $|x|\in F$.")
add("L13.PR","L13","§1 Properties (i)–(v)","Properties",r"(i) $|x|\ge0$, $=0$ iff $x=0$; (ii) $|x|=|-x|$; (iii) $-|x|\le x\le|x|$; (iv) $|x|\le a\iff -a\le x\le a$; (v) $|xy|=|x||y|$.")
add("L13.T11","L13","§1 Theorem 1.1 (triangle inequality)","Theorem 1.1 (Triangle inequality)",r"$|x+y|\le|x|+|y|$ in any ordered field.")
add("L13.D21","L13","§2 Definition 2.1 (metric)","Definition 2.1.",r"A **metric** $d$: positivity, symmetry, triangle inequality $d(x,z)\le d(x,y)+d(y,z)$.")
add("L13.E21","L13","§2 Example 2.1","Example 2.1.",r"$d(x,y)=|x-y|$ is the usual metric on $\mathbb R$.")
add("L13.E22","L13","§2 Example 2.2","Example 2.2.",r"$d(z,w)=|z-w|=\sqrt{(a-c)^2+(b-d)^2}$ on $\mathbb C$.")
add("L13.D22","L13","§2 Definition 2.2 (open ball)","Definition 2.2.",r"$B(z,r)=\{w\in S: d(w,z)<r\}$.")
add("L13.R21","L13","§2 Remark 2.1","Remark 2.1 (Notation)",r"The ball depends on the metric: write $B_d(z,r)$, $D_d(z,r)$.")
add("L13.E23","L13","§2 Example 2.3","Example 2.3.",r"In $\mathbb R$: $B(3,1)=(2,4)$. In $\mathbb C$: picture of $B(1+i,1)$.")
add("L13.D23","L13","§2 Definition 2.3 (open set)","Definition 2.3.",r"$U$ is open if $\forall x\in U\ \exists\varepsilon>0$ with $B(x,\varepsilon)\subseteq U$.")
add("L13.E24","L13","§2 Example 2.4","Example 2.4.",r"$(a,b)$ open; unions of open intervals open; $[1,2)$ not open; closed disc $D$ not open.")
add("L13.P21","L13","§2 Proposition 2.1","Proposition 2.1.",r"Every open set is a union of open balls.")
add("L13.P22","L13","§2 Proposition 2.2","Proposition 2.2.",r"Any union of open sets is open; a finite intersection of open sets is open.")
add("L13.R22","L13","§2 Remark 2.2","Remark 2.2.",r"$\varnothing$ and $S$ are open; $\bigcap_n(-\frac1n,\frac1n)=\{0\}$ is not open.")
add("L13.D24","L13","§2 Definition 2.4 (closed set)","Definition 2.4.",r"$C$ is closed if $S\setminus C$ is open.")
add("L13.E25","L13","§2 Example 2.5","Example 2.5.",r"$[a,b]$ is closed; $\{z\}$ is closed.")
add("L13.D25","L13","§2 Definition 2.5 (closed ball)","Definition 2.5.",r"$D(z,r)=\{w: d(w,z)\le r\}$.")
add("L13.P23","L13","§2 Proposition 2.3 (Fig. 1)","Proposition 2.3.",r"An open ball is open: for $z\in B(c,r)$ use $\varepsilon=r-d(z,c)$.")
add("L13.MAN","L13","§2 Same points, different distances","Same points, different distances",r"Manhattan distance $|x_1-y_1|+|x_2-y_2|$: its unit ball is a diamond.")
add("L13.X21","L13","§2 Exercise 2.1 (discrete metric)","Exercise 2.1 (The discrete metric)",r"Discrete metric: show it's a metric, describe its balls, every set is open and closed.")
add("L13.R23","L13","§2 Remark 2.3","Remark 2.3.",r"In $\mathbb R$ with the usual metric only $\varnothing$ and $\mathbb R$ are both open and closed.")
add("L13.D31","L13","§3 Definition 3.1 (norm)","Definition 3.1.",r"A **norm** on a field: $\|x\|\ge0$ ($=0$ iff $x=0$), $\|xy\|=\|x\|\|y\|$, $\|x+y\|\le\|x\|+\|y\|$.")
add("L13.E31","L13","§3 Example 3.1","Example 3.1.",r"The modulus is a norm on $\mathbb C$.")
add("L13.E32","L13","§3 Example 3.2","Example 3.2.",r"The absolute value is a norm on $\mathbb R$.")
add("L13.P31","L13","§3 Proposition 3.1","Proposition 3.1.",r"A norm induces a metric $d(x,y)=\|x-y\|$ (uses $\|1\|=\|-1\|=1$ for symmetry).")

# ---------------- Lecture 14 ----------------
add("L14.D11","L14","§1 Definition 1.1","Definition 1.1.",r"A sequence is a function $a:\mathbb N\to\mathbb C$, $a_n=a(n)$.")
add("L14.EX","L14","§1 Examples (i)–(vii)","constant sequence with value",r"Constant, $n$, $1/n$, $(-1)^n$, $i^n$, recursive $a_{n+1}=\sqrt{1+a_n}$, piecewise.")
add("L14.R1","L14","§1 Remark 1","Remark 1. Notice how general",r"A sequence needn't have a nice formula.")
add("L14.D12","L14","§1 Definition 1.2","Definition 1.2.",r"$(a_n)=(b_n)$ iff $a_n=b_n$ for every $n$.")
add("L14.D13","L14","§1 Definition 1.3","Definition 1.3.",r"Sum, difference, product, quotient ($b_n\ne0$) and scalar multiple of sequences, term by term.")
add("L14.D14","L14","§1 Definition 1.4","Definition 1.4.",r"The **range** is $\{a_n: n\in\mathbb N\}$.")
add("L14.R2","L14","§1 Remark 2","should not be confused",r"$(-1)^n$ has range $\{-1,1\}$; different sequences can share a range.")
add("L14.D15","L14","§1 Definition 1.5","Definition 1.5.",r"A **tail** is $(a_m,a_{m+1},\dots)$; e.g. $(5,6,7,\dots)$ is a tail of $a_n=n$.")
add("L14.D21","L14","§2 Definition 2.1","Definition 2.1.",r"$a_n\to a$ if $\forall\varepsilon>0\ \exists n_0(\varepsilon)$ with $|a_n-a|<\varepsilon$ for all $n\ge n_0(\varepsilon)$.")
add("L14.R3","L14","§2 Remark 3 (Fig. 3)","Remark 3.",r"$\forall\varepsilon>0\ \exists n_0(\varepsilon)\ \forall n\ge n_0:\ a_n\in B(a,\varepsilon)$.")
add("L14.R4","L14","§2 Remark 4","Remark 4. In the definition",r"$n_0$ depends on $\varepsilon$: a game against an opponent picking smaller $\varepsilon$.")
add("L14.R5","L14","§2 Remark 5","Remark 5. Given",r"Only finitely many terms ($a_1,\dots,a_{n_0-1}$) can lie outside $B(a,\varepsilon)$.")
add("L14.R6","L14","§2 Remark 6","Remark 6. The definition",r"A tail $(a_{n_0},a_{n_0+1},\dots)$ lies entirely in $B(a,\varepsilon)$.")
add("L14.TPL","L14","§2 Proof template","Proof template: how to show",r"Given $\varepsilon>0$, let $n_0(\varepsilon)=\dots$; then for $n\ge n_0$, $|a-a_n|\le\dots<\varepsilon$.")
add("L14.E21","L14","§2 Example 2.1","Example 2.1.",r"$\frac1n\to0$ with $n_0(\varepsilon)=[1/\varepsilon]+1$ (Archimedean property).")
add("L14.R7","L14","§2 Remark 7","Remark 7. The choice",r"Find $n_0$ by working backwards on scratch paper: $\frac1n<\varepsilon\iff n>\frac1\varepsilon$.")
add("L14.E22","L14","§2 Example 2.2","Example 2.2.",r"$1+\frac1{\sqrt n}\to1$ with $n_0=[1/\varepsilon^2]+1$.")
add("L14.X21","L14","§2 Exercise 2.1","Exercise 2.1.",r"Show $\frac1{n^2}\to0$ from the definition.")
add("L14.NEG","L14","§3 Negating the definition","Negating the definition of convergence",r"$a_n\not\to a$: $\exists\varepsilon>0\ \forall n_0\ \exists n\ge n_0$ with $|a_n-a|\ge\varepsilon$.")
add("L14.D31","L14","§3 Definition 3.1","Definition 3.1.",r"$(a_n)$ **diverges** if $\forall a\in\mathbb C\ \exists\varepsilon>0\ \forall n_0\ \exists n\ge n_0:\ |a_n-a|\ge\varepsilon$.")
add("L14.X31","L14","§3 Exercise 3.1","Exercise 3.1.",r"$a_n\not\to a$ iff some $\varepsilon>0$ has infinitely many terms with $|a_n-a|\ge\varepsilon$.")
add("L14.E31","L14","§3 Example 3.1","Example 3.1.",r"$(-1)^n$ diverges: take $\varepsilon=1$; $a$ is at distance $\ge1$ from $1$ or $-1$.")
add("L14.R8","L14","§3 Remark 8 (Fig. 4)","Remark 8.",r"No point is close to both $1$ and $-1$.")
add("L14.T41","L14","§4 Theorem 4.1","Theorem 4.1.",r"A convergent sequence has a unique limit (use $\varepsilon/2$ and the triangle inequality).")

# ---------------- Lecture 15 ----------------
add("L15.D11","L15","§1 Definition 1.1","Definition 1.1.",r"$(a_n)$ is bounded if $\exists M>0$ with $|a_n|\le M$ for all $n$.")
add("L15.R11","L15","§1 Remarks 1.1–1.2","Remark 1.1.",r"Equivalent: $\{|a_n|\}$ upper bounded; terms lie in $[-M,M]$ or $D(0,M)$.")
add("L15.T11","L15","§1 Theorem 1.1","Theorem 1.1.",r"Convergent $\Rightarrow$ bounded.")
add("L15.R13","L15","§1 Remark 1.3","Remark 1.3.",r"The converse fails: $(-1)^n$ is bounded but diverges.")
add("L15.T21","L15","§2 Theorem 2.1 (Comparison)","Theorem 2.1 (Comparison",r"If $a_n\to a$, $b_n\to b$ and $a_n\le b_n$ eventually, then $a\le b$.")
add("L15.R21","L15","§2 Remark 2.1","Remark 2.1.",r"Strict inequalities aren't preserved: $0<\frac1n$ but both limits are $0$.")
add("L15.T22","L15","§2 Theorem 2.2 (Squeeze)","Theorem 2.2 (Squeeze",r"$a_n\le b_n\le c_n$ eventually and $a_n,c_n\to L$ imply $b_n\to L$.")
add("L15.EX","L15","§2 Examples (i)–(ii)","n!",r"$\frac{\sin n}n\to0$; $\frac n{n!}\to0$.")
add("L15.P21","L15","§2 Proposition 2.1","Proposition 2.1.",r"If $(b_n)$ is bounded and $a_n\to0$, then $a_nb_n\to0$.")
add("L15.R22","L15","§2 Remark 2.2","Remark 2.2.",r"Aim for $\varepsilon/M$; e.g. $\frac{\sin n}n=\frac1n\sin n\to0$.")
