add("L16.R11","L16","§1 Remark 1.1 (Bernoulli)","Remark 1.1 (Bernoulli",r"$(1+a)^n\ge1+na$ for $a\ge-1$.")
add("L16.T11","L16","§1 Theorem 1.1 (geometric sequences)","Theorem 1.1.",r"$\alpha^n$: $\to1$ if $\alpha=1$; $\to0$ if $|\alpha|<1$; diverges if $|\alpha|=1,\alpha\ne1$; $|\alpha^n|\to\infty$ if $|\alpha|>1$.")
add("L16.R12","L16","§1 Remarks 1.2–1.4","Remark 1.2 (How to choose",r"Choosing $n_0$ backwards; case (iv) from case (ii); a logarithm approach.")
