add("L16.P31","L16","§3 Proposition 3.1 (ratio criterion)","Proposition 3.1.",r"If $|a_{n+1}/a_n|\to\ell<1$ then $a_n\to0$; if $\ell>1$ (or $\to\infty$) then $|a_n|\to\infty$.")
add("L16.R3X","L16","§3 Remarks 3.1–3.3","Remark 3.1.",r"No conclusion when $\ell=1$; the idea is comparison with a geometric sequence.")
add("L16.P32","L16","§3 Proposition 3.2 (root criterion)","Proposition 3.2.",r"If $\sqrt[n]{|a_n|}\to\ell<1$ then $a_n\to0$; if $\ell>1$ then $|a_n|\to\infty$.")
