add("PB.2b","PB","Problem 2(b)","Problem 2",r"If $|a-b|\le c$ for all $a\in A$, $b\in B$, prove $|\sup A-\sup B|\le c$.")
add("PB.3a","PB","Problem 3(a)","Problem 3",r"Using density of $\mathbb Q$ and irrationality of $\sqrt2$, show an irrational lies between any $a<b$.")
add("PB.3b","PB","Problem 3(b)","Problem 3",r"Prove neither $\mathbb Q$ nor $\mathbb R\setminus\mathbb Q$ is open or closed.")
add("PB.4a","PB","Problem 4(a)","Problem 4",r"Find all $z$ with $z+\bar z=6$ and $|z|=5$.")
add("PB.4b","PB","Problem 4(b)","Problem 4",r"Prove $|z+\bar z|\le2|z|$; when is it an equality?")
add("PB.4c","PB","Problem 4(c)","Problem 4",r"Find all nonzero $z$ with $\frac z{\bar z}=-1$.")
