add("PB.7b","PB","Problem 7(b)","Problem 7",r"Evaluate $\lim(\sqrt{n^2+3n}-n)$.")
add("PB.7c","PB","Problem 7(c)","Problem 7",r"If $a_n\to0$ and $a_nb_n\to0$, must $(b_n)$ be bounded?")
